-- Requires both installation candidates in a rollback-only transaction.
insert into auth.users(id,email,raw_user_meta_data) select ('66666666-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'connection-fixture-'||n||'@example.invalid',jsonb_build_object('first_name','Connection Fixture '||n) from generate_series(1,4) n;
insert into hs_shared_dates.verified_adults(user_id,verified_at,expires_at) select ('66666666-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,now()-interval '1 day',now()+interval '1 day' from generate_series(1,4) n;
create function pg_temp.assert_ok(p_test boolean,p_message text) returns void language plpgsql as $$begin if p_test is distinct from true then raise exception 'TEST FAILED: %',p_message;end if;end;$$;
create function pg_temp.fails(p_sql text,p_message text) returns void language plpgsql as $$begin begin execute p_sql;exception when others then if sqlerrm not like p_message then raise exception 'Wrong failure: % (expected %)',sqlerrm,p_message;end if;return;end;raise exception 'TEST FAILED: expected error';end;$$;
select set_config('request.jwt.claim.sub','66666666-0000-4000-8000-000000000001',true);
set local role authenticated;
select set_config('test.inviteA',(select row_to_json(x)::text from public.create_heart_stone_invitation('connection-fixture-2@example.invalid','Two') x),true);
select set_config('test.inviteB',(select row_to_json(x)::text from public.create_heart_stone_invitation('connection-fixture-3@example.invalid','Three') x),true);
select pg_temp.assert_ok(current_setting('test.inviteA')::jsonb->>'heart_stone_id'<>current_setting('test.inviteB')::jsonb->>'heart_stone_id','new relationships have distinct identities');
select pg_temp.fails($q$select public.accept_heart_stone_invitation(current_setting('test.inviteA')::jsonb->>'invitation_token')$q$,'INVITATION_NOT_FOR_ACCOUNT');
select set_config('request.jwt.claim.sub','66666666-0000-4000-8000-000000000002',true);
select pg_temp.assert_ok(public.accept_heart_stone_invitation(current_setting('test.inviteA')::jsonb->>'invitation_token')::text=current_setting('test.inviteA')::jsonb->>'heart_stone_id','recipient accepts A');
select pg_temp.assert_ok(public.accept_heart_stone_invitation(current_setting('test.inviteA')::jsonb->>'invitation_token')::text=current_setting('test.inviteA')::jsonb->>'heart_stone_id','accept retry stays in same connection');
select set_config('test.inviteC',(select row_to_json(x)::text from public.create_heart_stone_invitation('connection-fixture-4@example.invalid','Four') x),true);
select set_config('request.jwt.claim.sub','66666666-0000-4000-8000-000000000003',true);
select public.accept_heart_stone_invitation(current_setting('test.inviteB')::jsonb->>'invitation_token');
select pg_temp.assert_ok(public.get_alpha_bootstrap()->'heart_stone'->>'id'=current_setting('test.inviteB')::jsonb->>'heart_stone_id','single-connection bootstrap stays compatible');
select set_config('request.jwt.claim.sub','66666666-0000-4000-8000-000000000004',true);
select public.accept_heart_stone_invitation(current_setting('test.inviteC')::jsonb->>'invitation_token');
select set_config('request.jwt.claim.sub','66666666-0000-4000-8000-000000000001',true);
select pg_temp.assert_ok((select count(*) from public.heart_stone_memberships where user_id=auth.uid() and status='active')=2,'organizer has two active separate relationships');
select pg_temp.fails('select public.get_alpha_bootstrap()','CONNECTION_SELECTION_REQUIRED');
select pg_temp.assert_ok(public.get_alpha_bootstrap_for((current_setting('test.inviteA')::jsonb->>'heart_stone_id')::uuid)->'heart_stone'->>'id'=current_setting('test.inviteA')::jsonb->>'heart_stone_id','explicit bootstrap selects A');
select pg_temp.assert_ok(public.get_alpha_bootstrap_for((current_setting('test.inviteB')::jsonb->>'heart_stone_id')::uuid)->'heart_stone'->>'id'=current_setting('test.inviteB')::jsonb->>'heart_stone_id','explicit bootstrap selects B');
select pg_temp.fails($q$select public.get_alpha_bootstrap_for((current_setting('test.inviteC')::jsonb->>'heart_stone_id')::uuid)$q$,'not authorized%');
select pg_temp.assert_ok(jsonb_array_length(public.get_moment_invitation_partners((current_setting('test.inviteA')::jsonb->>'heart_stone_id')::uuid))=1,'A contains exactly its own partner');
select set_config('test.groupDate',(public.shared_date_action('create',auth.uid(),p_payload=>'{"participants":["66666666-0000-4000-8000-000000000001","66666666-0000-4000-8000-000000000002","66666666-0000-4000-8000-000000000003"],"title":"Cross-connection date","when":"Later","meeting":"Park"}',p_request_id=>'aaaaaaa1-0000-4000-8000-000000000001')->>'id'),true);
select public.shared_date_action('send',auth.uid(),current_setting('test.groupDate')::uuid,1,p_request_id=>'aaaaaaa1-0000-4000-8000-000000000002');
select set_config('request.jwt.claim.sub','66666666-0000-4000-8000-000000000002',true);
select pg_temp.assert_ok((select count(*) from public.heart_stone_memberships where user_id=auth.uid() and status='active')=2,'invitee may also have multiple connections');
select pg_temp.fails($q$select public.get_alpha_bootstrap_for((current_setting('test.inviteB')::jsonb->>'heart_stone_id')::uuid)$q$,'not authorized%');
select pg_temp.assert_ok(public.shared_date_action('respond',auth.uid(),current_setting('test.groupDate')::uuid,1,'{"response":"accepted"}','aaaaaaa1-0000-4000-8000-000000000003')->>'state'='pending','first invited person answers only for themselves');
select set_config('request.jwt.claim.sub','66666666-0000-4000-8000-000000000003',true);
select pg_temp.assert_ok(public.shared_date_action('respond',auth.uid(),current_setting('test.groupDate')::uuid,1,'{"response":"accepted"}','aaaaaaa1-0000-4000-8000-000000000004')->>'state'='confirmed','shared date confirms across separate connections');
set local role anon;
select pg_temp.fails('select public.create_heart_stone_invitation(''nobody@example.invalid'')','permission denied%');
reset role;
select pg_temp.assert_ok(to_regclass('public.one_active_heart_stone_per_user') is null,'legacy index removed only inside test');
select pg_temp.assert_ok((select count(*) from public.heart_stone_memberships where heart_stone_id=(current_setting('test.inviteA')::jsonb->>'heart_stone_id')::uuid)=2,'A never absorbs other partners');
select pg_temp.assert_ok((select count(*) from public.heart_stone_memberships where heart_stone_id=(current_setting('test.inviteB')::jsonb->>'heart_stone_id')::uuid)=2,'B never absorbs other partners');
select 'PASS: independent connections, invitations, bootstrap isolation and shared-date integration' as result;
